/* Floating Cat Widget — fully working, no errors */

body::after {
  content: "";
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 150px;
  height: 150px;
  border-radius: 18px;
  background-image: url("data:image/jpeg;base64,");
  background-size: cover;
  background-position: center;
  box-shadow: 0 12px 30px rgba(0,0,0,0.45);
  z-index: 999999999;
  pointer-events: none;
}
